package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class CaptureRequestBodyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property capture request body of observability config ")
  void test_capture_request_body_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> CaptureRequestBodyVO.tryFrom(null));
    Assertions.assertEquals(true, CaptureRequestBodyVO.from(true).isCaptureRequestBody());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class,
        () -> CaptureRequestBodyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", CaptureRequestBodyVO.from(true).toString());
  }
}
